"""Self-contained, offline archive contents. No scripts or external resources."""
from datetime import datetime
from html import escape
from urllib.parse import quote
from zoneinfo import ZoneInfo

STYLE = '''
*{box-sizing:border-box}body{margin:0;background:#f5f1fc;color:#321448;font:16px/1.5 system-ui,-apple-system,"Segoe UI",sans-serif}.page{max-width:1120px;margin:32px auto;padding:36px;background:#fff;border:1px solid #e5d9f5;border-radius:24px}.brand{display:inline-flex;align-items:center;gap:6px;font-size:28px;font-weight:800}.badge{display:inline-grid;place-items:center;width:40px;height:40px;border-radius:50%;background:#7015ef;color:#fff}h1{font-size:clamp(28px,4vw,44px);line-height:1.2;margin:24px 0 8px}.subtitle,.meta,footer{color:#705b83}.subtitle{margin:0 0 24px}.summary{display:flex;flex-wrap:wrap;align-items:center;gap:20px;padding:20px 24px;background:#f7f2ff;border:1px solid #e4d5fb;border-radius:16px;margin-bottom:28px}.student{flex:1;min-width:180px}.student strong{display:block;font-size:23px}.chip{display:inline-block;border-radius:24px;background:#eadbff;padding:5px 14px;font-size:14px;font-weight:650}.table-wrap{border:1px solid #e4d5fb;border-radius:16px;overflow:hidden}table{width:100%;border-collapse:collapse;text-align:left}th{background:#f7f2ff;color:#705383;font-size:14px;padding:15px 20px}td{padding:20px;border-top:1px solid #e9def6;vertical-align:top}.date{white-space:nowrap;font-weight:700}.time{display:block;font-size:13px;font-weight:400;color:#705b83}.topic{font-size:17px}.files{min-width:240px}.file{display:flex;gap:10px;align-items:center;min-height:44px;margin:4px 0;padding:8px 12px;border-radius:9px;background:#f3ebff;color:#6412cf;text-decoration:none;overflow-wrap:anywhere}.file:hover{background:#e7d6ff;text-decoration:underline}.file:focus-visible{outline:3px solid #7015ef;outline-offset:2px}.type{flex-shrink:0;font-size:10px;font-weight:750;border:1px solid #cdb3ee;border-radius:4px;padding:2px 4px}.tip{padding:14px 18px;background:#f7f2ff;border-radius:12px;margin:24px 0}.meta{font-size:13px}footer{margin-top:24px;padding-top:18px;border-top:1px solid #e5d9f5;text-align:center;font-size:14px}@media(max-width:640px){body{background:#fff}.page{margin:0;padding:20px 16px;border:0;border-radius:0}.summary{gap:12px;padding:16px}.student{flex-basis:100%}.table-wrap{border:0;overflow:visible}table,tbody,tr,td{display:block;width:100%}thead{display:none}tr{border:1px solid #e4d5fb;border-radius:14px;margin-bottom:14px;padding:14px}td{padding:0;border:0}.date{margin-bottom:4px}.time{display:inline;margin-left:8px}.topic{margin-bottom:10px}.files{min-width:0}.file{margin-top:8px}h1{margin-top:24px}}@media print{body{background:#fff}.page{margin:0;border:0;padding:0}.file{background:#fff}tr{break-inside:avoid}}
'''

def render_contents(entries, tz, student_name=''):
    zone = ZoneInfo(tz)
    dates = [datetime.fromtimestamp(row['starts_at'], zone) for row in entries]
    period = (min(dates).strftime('%d.%m.%Y') + ' — ' + max(dates).strftime('%d.%m.%Y')) if dates else ''
    rows = []
    for entry, date in zip(entries, dates):
        links = []
        for path in entry['links']:
            name = path.rsplit('/', 1)[-1]
            kind = name.rsplit('.', 1)[-1].upper()
            links.append('<a class="file" href="' + escape(quote(path, safe='/'), quote=True) + '"><span class="type" aria-hidden="true">' + escape(kind) + '</span><span>' + escape(name) + '</span></a>')
        rows.append('<tr><td class="date"><time datetime="' + date.isoformat() + '">' + date.strftime('%d.%m.%Y') + '</time><span class="time">' + date.strftime('%H:%M') + '</span></td><td class="topic">' + escape(entry.get('topic') or 'Математика') + '</td><td class="files">' + ''.join(links) + '</td></tr>')
    count = sum(len(row['links']) for row in entries)
    return ('<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Архив занятий — Просто 5</title><style>' + STYLE + '</style></head><body><main class="page"><div class="brand">Просто <span class="badge">5</span></div><h1>Архив занятий</h1><p class="subtitle">Все материалы занятий в одном месте</p><section class="summary" aria-label="Об архиве"><div class="student"><strong>' + escape(student_name or 'Материалы ученика') + '</strong><span>Математика</span></div><span>' + escape(period) + '</span><span class="chip">Занятий: ' + str(len(entries)) + '</span><span class="chip">Файлов: ' + str(count) + '</span></section><div class="table-wrap"><table aria-label="Материалы по занятиям"><thead><tr><th scope="col">Дата</th><th scope="col">Тема занятия</th><th scope="col">Материалы</th></tr></thead><tbody>' + ''.join(rows) + '</tbody></table></div><p class="tip">Нажмите на название файла, чтобы открыть материал.</p><p class="meta">Часовой пояс занятий: ' + escape(tz) + '</p><footer>Материалы доступны без интернета. Сначала распакуйте ZIP-архив целиком, сохранив структуру папок.</footer></main></body></html>')
